package engine

import "regexp"

// Rules are original OTS heuristic indicators, not a copy of ScanRepo's proprietary engine.
type Rule struct {
	ID, Category, Title, Severity, Detail, Pattern string
	Re                                             *regexp.Regexp
	Weight                                         int
}

func r(id, category, title, severity, detail, pattern string, weight int) Rule {
	return Rule{id, category, title, severity, detail, pattern, regexp.MustCompile(pattern), weight}
}

